"use strict";
// fn-launch-sw.js - generated by tools/fn_launcher.py. Serves the stored game out of
// IndexedDB with the two headers that grant cross-origin isolation, and answers Range.

var DB_NAME = "fn-launcher-vault";
var DB_VERSION = 1;
var GAME_NAME = "__fortnite.html";
var GAME_PATH = new URL(GAME_NAME, self.registration.scope).pathname;

var POLICY = {
  "Content-Type": "text/html; charset=utf-8",
  "Cross-Origin-Opener-Policy": "same-origin",
  "Cross-Origin-Embedder-Policy": "require-corp",
  "Cross-Origin-Resource-Policy": "same-origin",
  "Cache-Control": "no-store",
  "X-Content-Type-Options": "nosniff",
  "Accept-Ranges": "bytes"
};

self.addEventListener("install", function (event) {
  event.waitUntil(self.skipWaiting());
});

self.addEventListener("activate", function (event) {
  event.waitUntil(self.clients.claim());
});

function openDb() {
  return new Promise(function (res, rej) {
    var r = indexedDB.open(DB_NAME, DB_VERSION);
    r.onupgradeneeded = function () {
      var d = r.result;
      if (!d.objectStoreNames.contains("meta")) d.createObjectStore("meta");
      if (!d.objectStoreNames.contains("chunks")) d.createObjectStore("chunks");
    };
    r.onsuccess = function () { res(r.result); };
    r.onerror = function () { rej(r.error); };
  });
}

function readOnly(db, store, key) {
  return new Promise(function (res, rej) {
    var q = db.transaction(store, "readonly").objectStore(store).get(key);
    q.onsuccess = function () { res(q.result || null); };
    q.onerror = function () { rej(q.error); };
  });
}

// null = serve the whole body, [start, end) = a 206, "invalid" = 416. A multi-range or junk
// header is answered with the whole body, which is what a Range-unaware server does.
function parseRange(header, size) {
  if (!header) return null;
  var m = /^bytes=(\d*)-(\d*)$/.exec(String(header).trim());
  if (!m) return null;
  if (m[1] === "" && m[2] === "") return null;
  var start, end;
  if (m[1] === "") {
    var n = parseInt(m[2], 10);
    if (!n) return "invalid";
    start = Math.max(0, size - n);
    end = size;
  } else {
    start = parseInt(m[1], 10);
    end = m[2] === "" ? size : Math.min(size, parseInt(m[2], 10) + 1);
  }
  if (start >= size || start >= end) return "invalid";
  return [start, end];
}

// The chunked body: pull one chunk at a time, slice the edges, never hold more than one.
function bodyFor(db, meta, start, end) {
  var cs = meta.chunkSize;
  var pos = start;
  return new ReadableStream({
    pull: function (ctrl) {
      if (pos >= end) { ctrl.close(); return Promise.resolve(); }
      var idx = Math.floor(pos / cs);
      return readOnly(db, "chunks", idx).then(function (chunk) {
        if (!chunk) {
          ctrl.error(new Error("vault is missing chunk " + idx + " - the download did not finish"));
          return;
        }
        var base = idx * cs;
        var from = pos - base;
        var to = Math.min(chunk.byteLength, end - base);
        if (to <= from) {
          ctrl.error(new Error("vault chunk " + idx + " is short (" + chunk.byteLength + " bytes)"));
          return;
        }
        ctrl.enqueue(chunk.slice(from, to));
        pos = base + to;
      });
    }
  });
}

function serve(request) {
  return openDb().then(function (db) {
    return readOnly(db, "meta", "game").then(function (meta) {
      if (!meta || !meta.size) {
        return new Response("Nothing stored yet - open the launcher.", {
          status: 404,
          headers: { "Content-Type": "text/plain; charset=utf-8", "Cache-Control": "no-store" }
        });
      }
      var size = meta.size;
      var range = parseRange(request.headers.get("range"), size);
      if (range === "invalid") {
        var h416 = Object.assign({}, POLICY, { "Content-Range": "bytes */" + size });
        return new Response("Range not satisfiable", { status: 416, headers: h416 });
      }
      var start = range ? range[0] : 0;
      var end = range ? range[1] : size;
      var headers = Object.assign({}, POLICY, { "Content-Length": String(end - start) });
      if (range) headers["Content-Range"] = "bytes " + start + "-" + (end - 1) + "/" + size;
      var status = range ? 206 : 200;
      if (request.method === "HEAD") return new Response(null, { status: status, headers: headers });
      return new Response(bodyFor(db, meta, start, end), { status: status, headers: headers });
    });
  }).catch(function (e) {
    return new Response("launcher vault error: " + (e && e.message ? e.message : e), {
      status: 500,
      headers: { "Content-Type": "text/plain; charset=utf-8", "Cache-Control": "no-store" }
    });
  });
}

self.addEventListener("fetch", function (event) {
  if (event.request.method !== "GET" && event.request.method !== "HEAD") return;
  var url = new URL(event.request.url);
  if (url.origin !== self.location.origin) return;
  if (url.pathname !== GAME_PATH) return;
  event.respondWith(serve(event.request));
});
